import { z } from "zod";

/** Technical limit: upper bound of a Prisma `Int` (T-005 §1, M-15). Not clinical. */
export const MAX_DB_INT = 2147483647;

/** UUID (RFC 9562, version and variant checked) generated by whoever creates the data (`crypto.randomUUID()`), T-005 §1. */
export const UuidSchema = z.uuid();

/** ISO 8601 in UTC with milliseconds and `Z` only; offsets are rejected (T-005 §1). */
export const IsoDateTimeSchema = z.iso.datetime({ precision: 3 });

/** Integer that fits a Prisma `Int` (technical limit, not clinical). */
export const DbIntSchema = z.number().int().lte(MAX_DB_INT);

/** Integer from 1 to MAX_DB_INT, e.g. versions and sequences (technical limit, not clinical). */
export const PositiveDbIntSchema = DbIntSchema.gte(1);

/** Integer from 0 to MAX_DB_INT (technical limit, not clinical). */
export const NonNegativeDbIntSchema = DbIntSchema.gte(0);

/**
 * Free text validated WITHOUT transforming it (no trim): rejects empty or whitespace-only
 * strings. Length is counted with `String.prototype.length` (UTF-16 code units, Q9).
 * `min`/`max` are format limits, never clinical.
 */
export function NonBlankText(min: number, max: number) {
  return z
    .string()
    .min(min)
    .max(max)
    .refine((text) => text.trim().length > 0, { message: "Text must not be blank" });
}

/** Demo-mode role sent in the `X-Demo-Role` header. It is not authentication. */
export const DemoRoleSchema = z.enum(["SHIP", "EARTH"]);
export type DemoRole = z.infer<typeof DemoRoleSchema>;

/** Direction of anything that crosses the ship-Earth channel. */
export const DirectionSchema = z.enum(["SHIP_TO_EARTH", "EARTH_TO_SHIP"]);
export type Direction = z.infer<typeof DirectionSchema>;
